from pathlib import Path
import re,collections,yaml
p=Path('candidate/statement-ledger.md'); ls=p.read_text().splitlines(); ti=next(i for i,s in enumerate(ls) if s.startswith('Totals:'))
sec=None;rows=[];heads={};pointers={}
for i,s in enumerate(ls[ti:],ti+1):
 if s.startswith('## '):
  sec=s.split(' ',2)[1];heads[sec]=re.match(r'## \\w+ \\((whole result|narrower results?|foundation|proof steps)',s).group(1)
 if re.match(r'\\| .*\\| "'`StratonovichHAM'"',s):
  cells=re.split(r'(?<"'!'"\\\\)\\|',s)[1:-1]; lab=re.match(r'"'`([''^`]+)`'"',cells[0].strip());rows.append((i,sec,lab.group(1) if lab else None,cells[1].strip(' "'`'"')))
print('Independent ledger counts:',len(rows),'distinct',len(set(r[3] for r in rows)), 'labelled',sum(r[2] is not None for r in rows), 'unlabelled',sum(r[2] is None for r in rows))
cl=yaml.safe_load(Path('lean/claims.yaml').read_text())['claims'];print('claims kinds:',dict(collections.Counter(x['kind'] for x in cl))); print('claim identifiers equal table:',{x['decl'] for x in cl}=={r[3] for r in rows})
cov=yaml.safe_load(Path('lean/coverage.yaml').read_text())['rows'];print('coverage classes:',dict(collections.Counter(r['class'] for r in cov)));print('coverage class/conclusion:',dict(collections.Counter((r['class'],r.get('conclusion')) for r in cov)))
co=Path('lean/COMPLETION.md').read_text().split('## Every labelled result')[1]; cr=[s.split('|')[1:-1] for s in co.splitlines() if s.startswith('| "'`'"')];print('COMPLETION results:',len(cr),dict(collections.Counter(r[-1].strip() for r in cr)))
for s in ls[ls.index('## Index by label')+1:ti]:
 if s.startswith('| "'`'"') or s.startswith('| no direct label'):
  cells=re.split(r'(?<"'!'"\\\\)\\|',s)[1:-1]; lab=cells[0].strip().strip('"'`'"'); pointers[lab]=re.findall(r'"'`('"\\w+)"'` '"\\((["'^)]+)'"\\)',cells[1])
actual={(r[2] or 'no direct label',r[1]) for r in rows}; declared={(lab,sec) for lab,ents in pointers.items() for sec,cat in ents}; print('pointer rows',len(pointers),'pairs',len(declared),'missing',actual-declared,'extra',declared-actual);print('category mismatches',[(lab,sec,cat,heads[sec]) for lab,ents in pointers.items() for sec,cat in ents if heads.get(sec)"'!=cat])
print('"'Coverage/Completion status mismatches:')
cm={r[0].strip(' "'`'"'):r[-1].strip() for r in cr};trans={('same-assumptions','full'):'formalized, manuscript hypotheses',('same-assumptions','weaker'):'formalized, manuscript hypotheses, narrower conclusion',('inputs-supplied','weaker'):'inputs supplied, steps/narrower',('outside',None):'outside Lean (main theorem)'}
for r in cov:
 lab=r['paper']['label'];expected=trans.get((r['class'],r.get('conclusion')))
 if lab in cm and cm[lab]"'!=expected:print(lab,expected,cm[lab])
print('"'COMPLETION statuses without corresponding coverage:',[(lab,s) for lab,s in cm.items() if s"'!='"'not formalized' and lab not in {r['paper']['label'] for r in cov}])
